{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Acarbose, a polar carbohydrate-based drug, has poor systemic bioavailability in animals and humans, with most of the dose remaining in the intestinal lumen; this supports low oral bioavailability for the similarly polar, carbohydrate-rich query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pentosan polysulfate, a sulfated polysaccharide, has oral bioavailability ≤3% in humans; the query's sulfate ester and sugar backbone make this directly relevant to predicting very low absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Tobramycin, a highly polar aminoglycoside, has low and virtually negligible oral bioavailability and requires parenteral administration; the query's multiple polar and ionizable groups similarly preclude meaningful oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Glycyrrhizin, a glycoside bearing glucuronic acid, has poor oral bioavailability in humans with the parent drug barely detectable after oral dosing; the query also contains a glucuronic acid moiety and glycosidic linkages.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Scutellarin, a glucuronide-containing polar glycoside, has only 10.67% oral bioavailability in humans, below the 20% threshold; this supports low bioavailability for the query's glucuronide-containing structure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an extremely polar, ionizable sulfated glycosaminoglycan disaccharide. All transferable experimental evidence from polar carbohydrate, sulfated polysaccharide, glucuronide, and aminoglycoside analogues indicates oral bioavailability far below 20% (typically <2-5%). The physicochemical prior also strongly predicts negligible passive permeability. Therefore, predict low oral bioavailability.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the exact query molecule.",
    "Morgan similarity scores to evidence molecules are modest (~0.23-0.28), so quantitative transfer is uncertain.",
    "Possible active uptake or transporter effects for the query are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

